[
  {
    "statement": "No studies were found that evaluated the effects of limiting the number of dredges per vessel on marine fish populations.",
    "citations": []
  },
  {
    "statement": "Related research on dredging restrictions shows mixed results.",
    "citations": []
  },
  {
    "statement": "One study found that ceasing shellfish dredging in the North Sea for 10 years had no effect on species richness or abundance of bottom-dwelling fish.",
    "citations": []
  },
  {
    "statement": "A study in the Firth of Lorn found that prohibiting dredging in a marine protected area for approximately 2.5 years resulted in different combined invertebrate and fish community composition compared to unprotected dredged sites.",
    "citations": []
  }
]

[
  {
    "statement": "Based on available evidence, there are no studies that have evaluated the effects of maximum landing sizes on fish reproductive success.",
    "citations": [
      "2736"
    ]
  },
  {
    "statement": "The lack of studies on maximum landing sizes makes a direct comparison to minimum landing sizes impossible.",
    "citations": [
      "2736"
    ]
  },
  {
    "statement": "For minimum landing sizes, evidence of their effect on fish reproductive success is limited and mixed.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "One global review found only one of five swordfish fisheries showed increased recruitment after implementing minimum sizes and catch limits.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "A replicated study in the Ionian Sea found that despite minimum size regulations, most commercially caught fish remained immature and had never spawned.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "Three other studies on minimum landing sizes focused on unwanted catch reduction rather than on reproductive success.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "The three studies on minimum landing sizes that focused on unwanted catch reduction showed inconsistent results.",
    "citations": [
      "2735"
    ]
  },
  {
    "statement": "No comparative research exists specifically examining how different size limit approaches, such as maximum and minimum landing sizes, affect reproductive outcomes.",
    "citations": []
  }
]
